/**
 * The Vaanika horizontal logo for dark backgrounds (design/logo/svg/
 * vaanika-horizontal-colour-transparent-for-dark-bg.svg, unchanged), for PDF headers and share pages
 * when a business profile has no uploaded logo. Generated from the design file; do not edit by hand.
 */
import { DEFAULT_BRAND } from '@shubhjets/shared';

export const VAANIKA_LOGO_ON_DARK = `data:image/svg+xml;base64,`;

/** The uploaded logo, else the Vaanika artwork when the brand is Vaanika, else null (text wordmark). */
export function brandLogo(uploaded: string | null | undefined, brandName: string): string | null {
  if (uploaded) return uploaded;
  return brandName.trim().toLowerCase() === DEFAULT_BRAND.toLowerCase()
    ? VAANIKA_LOGO_ON_DARK
    : null;
}
